def gen(rng):
    from itertools import combinations_with_replacement
    arm = set(range(10))
    for k in range(2, 9):
        for combo in combinations_with_replacement(range(10), k):
            if combo[-1] == 0:
                continue
            v = sum(d ** k for d in combo)
            if len(str(v)) == k and sorted(str(v)) == sorted(str(c) for c in combo):
                arm.add(v)
    arm = sorted(arm)
    tests = [str(x) for x in (0, 1, 9, 10, 153, 154, 370, 371, 407, 100, 9474, 9475, 1634, 8208)]
    for _ in range(8):
        tests.append(str(rng.choice(arm)))
    for _ in range(8):
        x = rng.choice(arm)
        tests.append(str(x + rng.choice([-1, 1, 10, -10]) if x > 10 else x + 1))
    for _ in range(6):
        tests.append(str(rng.randint(0, 99999)))
    tests += ['4679307774', '4679307775', '28116440335967', '28116440335968', '1000000000000000', '999999999999999', '123456789012345']
    return tests

